import json
from pathlib import Path
F={}
def add(slug,symbol,jsx,selector=None,fill=None):
 F[slug]={'symbol':symbol,'jsx':jsx}
 if selector:F[slug]['action']={'selector':selector,**({'fill':fill} if fill else {})}
add('assistant-ui-elements-tool-call','ToolCall','<C.ToolCall label="Searched project files" activeLabel="Searching files" query="design tokens" request="Find shared colour tokens" result="Found 12 matching definitions in appearance.json" running={false} open={open} onOpenChange={setOpen}/>','button')
add('ai-elements-reasoning','Reasoning','<C.Reasoning><C.ReasoningTrigger/><C.ReasoningContent>{"Compare the available sources, check the constraints, then choose the smallest complete change."}</C.ReasoningContent></C.Reasoning>','button')
add('ai-elements-sources','Sources','<C.Sources><C.SourcesTrigger count={3}/><C.SourcesContent><C.Source href="#" title="Design foundations"/><C.Source href="#" title="Component adoption rules"/><C.Source href="#" title="Observation contract"/></C.SourcesContent></C.Sources>','button')
add('elements-chat-input','AiChatInput','<C.AiChatInput allowAttachments placeholder="Ask about the project…" onSubmit={()=>{}}/>','textarea','Compare the component options and their dependencies.')
add('assistant-ui-elements-composer','Composer','<C.Composer><C.ComposerBar><C.ComposerInput value={value} onChange={e=>setValue(e.target.value)} placeholder="Ask a question…"/><C.ComposerActions><C.ComposerSend disabled={!value} onClick={()=>setValue(\'\')}/></C.ComposerActions></C.ComposerBar></C.Composer>','input','Show the approved components for this project.')
add('ai-elements-prompt-input','PromptInput','<C.PromptInput onSubmit={()=>{}}><C.PromptInputBody><C.PromptInputTextarea placeholder="What would you like to build?"/></C.PromptInputBody><C.PromptInputFooter><C.PromptInputSubmit/></C.PromptInputFooter></C.PromptInput>','textarea','Review the pilot shortlist and explain the trade-offs.')
add('assistant-ui-elements-terminal-block','TerminalBlock','<C.TerminalBlock command="npm run build" lines={["Building the component preview…","✓ 24 components checked","Build complete in 1.8 seconds"]} visibleCount={3} done maxCollapsedLines={1}/>','button[aria-expanded]')
add('ai-elements-code-block','CodeBlock','<C.CodeBlock code={"const approved = components.filter(item => item.status === \'approved\');\\nconsole.log(approved.length);"} language="javascript"><C.CodeBlockHeader><C.CodeBlockTitle>review.js</C.CodeBlockTitle><C.CodeBlockCopyButton/></C.CodeBlockHeader></C.CodeBlock>','button')
