add('assistant-ui-elements-data-table','DataTable','<C.DataTable caption="Pilot review" columns={[{key:"name",label:"Component",sortable:true},{key:"votes",label:"Reviews",sortable:true,format:{kind:"number"}}]} rows={[{name:"Prompt input",votes:8},{name:"Code block",votes:12},{name:"Data table",votes:6}]} rowKey="name"/>','thead button')
add('assistant-ui-elements-spec-sheet','SpecSheet','<C.SpecSheet title="Component intake" subtitle="Review snapshot" visibleCount={4} rows={[{label:"Licence",value:"MIT",emphasis:true},{label:"Dependencies",value:"3 packages"},{label:"Porting effort",value:"Medium"},{label:"Status",value:"Awaiting review"}]}/>')
add('kibo-ui-table','TableProvider','<C.TableProvider columns={[{accessorKey:"name",header:({column})=><C.TableColumnHeader column={column} title="Component"/>},{accessorKey:"status",header:"Status"}]} data={[{name:"Prompt input",status:"Review"},{name:"Code block",status:"Approved"},{name:"Search",status:"Review"}]}><C.TableHeader>{({headerGroup:hg})=><C.TableHeaderGroup headerGroup={hg} key={hg.id}>{({header})=><C.TableHead header={header} key={header.id}/>}</C.TableHeaderGroup>}</C.TableHeader><C.TableBody>{({row})=><C.TableRow row={row} key={row.id}>{({cell})=><C.TableCell cell={cell} key={cell.id}/>}</C.TableRow>}</C.TableBody></C.TableProvider>','thead button')
add('assistant-ui-elements-chart','Chart','<C.Chart label="Components reviewed" value="24" delta="+8 this week" points={[4,8,6,12,10,18,16,24]} visibleCount={8} variant="area"/>')
add('kibo-ui-contribution-graph','ContributionGraph','<C.ContributionGraph data={Array.from({length:182},(_,i)=>({date:new Date(Date.UTC(2026,0,i+1)).toISOString().slice(0,10),count:i%5,level:i%5}))} maxLevel={4}><C.ContributionGraphCalendar>{({activity,dayIndex,weekIndex})=><C.ContributionGraphBlock activity={activity} dayIndex={dayIndex} weekIndex={weekIndex}/>}</C.ContributionGraphCalendar><C.ContributionGraphFooter><C.ContributionGraphTotalCount/><C.ContributionGraphLegend/></C.ContributionGraphFooter></C.ContributionGraph>')
