add('ai-elements-file-tree','FileTree','<C.FileTree><C.FileTreeFolder path="src" name="src"><C.FileTreeFile path="src/app.tsx" name="app.tsx"/><C.FileTreeFile path="src/style.css" name="style.css"/></C.FileTreeFolder><C.FileTreeFile path="README.md" name="README.md"/></C.FileTree>','[role="treeitem"] button,button')
add('assistant-ui-elements-file-tree','FileTree','<C.FileTree nodes={[{path:"src",name:"src",kind:"folder",depth:0},{path:"src/app.tsx",name:"app.tsx",kind:"file",depth:1,additions:24,deletions:3},{path:"src/style.css",name:"style.css",kind:"file",depth:1,additions:12,deletions:2}]} visibleCount={3} totalAdditions={36} totalDeletions={5}/>')
add('kibo-ui-dropzone','Dropzone','<C.Dropzone maxFiles={3}><C.DropzoneEmptyState/><C.DropzoneContent/></C.Dropzone>')
add('assistant-ui-elements-command-palette','CommandPalette','<C.CommandPalette commands={[{id:"open",label:"Open component library",group:"Navigate",keys:["⌘","K"]},{id:"review",label:"Review pilot",group:"Navigate",keys:["R"]},{id:"export",label:"Export reviews",group:"Actions",keys:["E"]}]} query={value} activeId={active} onQueryChange={setValue} onActiveChange={setActive} onRun={()=>{}}/>','input','review')
add('diceui-command-stack','CommandStack','<C.CommandStack><C.CommandStackInput placeholder="Search commands…"/><C.CommandStackList><C.CommandStackPage value="root"><C.CommandStackGroup heading="Navigate"><C.CommandStackItem value="library">Component library</C.CommandStackItem><C.CommandStackItem value="review">Review pilot</C.CommandStackItem></C.CommandStackGroup></C.CommandStackPage></C.CommandStackList></C.CommandStack>','input','review')
