add('coss-toast','ToastProvider','<C.ToastProvider><button onClick={()=>C.toastManager.add({title:"Review saved",description:"Your vote can be edited at any time."})} className="rounded-md border px-4 py-2">Save review</button></C.ToastProvider>','button')
add('assistant-ui-elements-error-state','ErrorState','<C.ErrorState title="Could not load the attachment" detail="Check your connection, then try again." retrying={open} onRetry={()=>setOpen(true)}/>','button')
add('kibo-ui-banner','Banner','<C.Banner inset><C.BannerTitle>The pilot is ready for your review.</C.BannerTitle><C.BannerAction onClick={()=>setOpen(true)}>Review components</C.BannerAction><C.BannerClose/></C.Banner>','button')
Path(__file__).with_name('fixtures.json').write_text(json.dumps(F,indent=2))
